"""A buildless local evidence viewer. All displayed metrics come from saved observations."""
import json


def render(summary):
    payload = {"tax": summary["tax"], "methods": summary["data_quality"]["per_method"],
               "profile": summary["data_quality"]["profile"], "tests": summary["tests"],
               "pipeline": {k: v for k,v in summary["pipeline"].items() if k not in {"pending_review", "hard_alerts"}},
               "generated_at": summary["generated_at"]}
    return PAGE.replace("__DATA__", json.dumps(payload, ensure_ascii=False).replace("<", "\\u003c"))


